begin;

create extension if not exists pgcrypto;

create schema if not exists private;
revoke all on schema private from public;

create table if not exists public.households (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  created_at timestamptz not null default now(),
  unique (name)
);

create table if not exists public.household_members (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  display_name text,
  role text not null default 'member' check (role in ('owner', 'member')),
  created_at timestamptz not null default now(),
  unique (household_id, user_id),
  unique (user_id)
);

create table if not exists public.accounts (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  owner_member_id uuid references public.household_members(id) on delete set null,
  name text not null,
  kind text,
  color text,
  source_metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (household_id, name)
);

create table if not exists public.import_batches (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  imported_by uuid references auth.users(id) on delete set null,
  filename text not null,
  status text not null default 'processing'
    check (status in ('processing', 'completed', 'completed_with_warnings', 'failed')),
  row_count integer not null default 0 check (row_count >= 0),
  warning_count integer not null default 0 check (warning_count >= 0),
  month_start date,
  month_end date,
  source_metadata jsonb not null default '{}'::jsonb,
  imported_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  name text not null,
  slug text not null,
  color text,
  included_in_consumption boolean not null default true,
  created_at timestamptz not null default now(),
  unique (household_id, name),
  unique (household_id, slug)
);

create table if not exists public.subcategories (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  category_id uuid not null references public.categories(id) on delete cascade,
  name text not null,
  slug text not null,
  created_at timestamptz not null default now(),
  unique (category_id, name),
  unique (category_id, slug)
);

create table if not exists public.precise_types (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  subcategory_id uuid not null references public.subcategories(id) on delete cascade,
  name text not null,
  slug text not null,
  created_at timestamptz not null default now(),
  unique (subcategory_id, name),
  unique (subcategory_id, slug)
);

create table if not exists public.operations (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households(id) on delete cascade,
  account_id uuid references public.accounts(id) on delete set null,
  person_member_id uuid references public.household_members(id) on delete set null,
  import_batch_id uuid references public.import_batches(id) on delete set null,
  date date not null,
  import_month date not null check (extract(day from import_month) = 1),
  amount numeric(14, 2) not null,
  debit numeric(14, 2),
  credit numeric(14, 2),
  source_label text not null,
  normalized_merchant text,
  flow text not null
    check (flow in (
      'Dépense',
      'Revenu',
      'Remboursement',
      'Transfert interne',
      'Prêt et avance',
      'Flux technique'
    )),
  category_id uuid references public.categories(id) on delete set null,
  subcategory_id uuid references public.subcategories(id) on delete set null,
  precise_type_id uuid references public.precise_types(id) on delete set null,
  recurrence text check (recurrence is null or recurrence in ('Fixe', 'Variable')),
  importance text check (
    importance is null or importance in (
      'Indispensable',
      'Contrainte',
      'Ajustable',
      'Optionnelle'
    )
  ),
  analytical_status text not null default 'Habituel'
    check (analytical_status in ('Habituel', 'Exceptionnel', 'Hors budget', 'À ventiler')),
  note text,
  event text,
  event_detail text,
  spending_context text
    constraint operations_spending_context_check
    check (
      spending_context is null
      or spending_context in ('Vie courante', 'Événement')
    ),
  resource_type text
    constraint operations_resource_type_check
    check (
      resource_type is null or resource_type in (
        'Revenu',
        'Entrée d''argent',
        'Remboursement',
        'Transfert interne',
        'Flux technique',
        'À qualifier'
      )
    ),
  resource_context text,
  analysis_month_override date
    constraint operations_analysis_month_override_check
    check (
      analysis_month_override is null
      or (
        amount > 0
        and extract(day from analysis_month_override) = 1
      )
    ),
  reimburses_operation_id uuid
    constraint operations_reimburses_operation_id_fkey
    references public.operations(id) on delete set null,
  constraint operations_reimbursement_link_check
    check (
      reimburses_operation_id is null
      or (resource_type = 'Remboursement' and amount > 0)
    ),
  uncertain boolean not null default false,
  fingerprint text not null,
  source_metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

